import type { CameraImageAdjustments } from './cameraProfile';

function bounded(value: number, min: number, max: number, fallback: number): number {
  return Number.isFinite(value) ? Math.max(min, Math.min(max, value)) : fallback;
}

/**
 * In-place, straight-alpha RGBA correction. Fully transparent pixels are untouched.
 * Brightness multiplies linear channel values, contrast pivots around 127.5,
 * then clamped channels receive gamma (power 1/gamma). Saturation mixes the
 * corrected channels around Rec.709 luma. Grayscale instead takes source luma
 * before the same tone LUT, so its tone curve is independent of saturation.
 * LUT entries retain floating-point precision until the final byte assignment.
 */
export function adjustCameraPixels(data: Uint8ClampedArray, settings: CameraImageAdjustments): void {
  const brightness = bounded(settings.brightness, 0, 3, 1);
  const contrast = bounded(settings.contrast, 0, 3, 1);
  const saturation = bounded(settings.saturation, 0, 3, 1);
  const gamma = bounded(settings.gamma, 0.1, 5, 1);
  if (brightness === 1 && contrast === 1 && saturation === 1 && gamma === 1 && !settings.grayscale) return;

  const lut = new Float64Array(256);
  for (let i = 0; i < lut.length; i++) {
    const linear = Math.max(0, Math.min(255, (i * brightness - 127.5) * contrast + 127.5));
    lut[i] = 255 * Math.pow(linear / 255, 1 / gamma);
  }
  // Interpolate fractional luma rather than quantizing it before tone correction.
  const tone = (value: number) => {
    const lo = Math.floor(value);
    return lut[lo] + (lut[Math.min(255, lo + 1)] - lut[lo]) * (value - lo);
  };
  for (let i = 0; i + 3 < data.length; i += 4) {
    if (data[i + 3] === 0) continue;
    const r = data[i], g = data[i + 1], b = data[i + 2];
    if (settings.grayscale) {
      const gray = tone(Math.min(255, 0.2126 * r + 0.7152 * g + 0.0722 * b));
      data[i] = data[i + 1] = data[i + 2] = gray;
    } else {
      const cr = lut[r], cg = lut[g], cb = lut[b];
      const luma = 0.2126 * cr + 0.7152 * cg + 0.0722 * cb;
      data[i] = luma + (cr - luma) * saturation;
      data[i + 1] = luma + (cg - luma) * saturation;
      data[i + 2] = luma + (cb - luma) * saturation;
    }
  }
}
